def find_numbers_in_range(a1, b1, a2, b2, L, R):
    count = 0
    # Handle negative values and zeros separately
    if b1 == 0 and b2 == 0:
        if L % a1 == L % a2:
            count += 1
        if (R - L) % a2 == 0:
            count += 1
    elif abs(b1) <= a1 and abs(b2) <= a2:
        if L % a1 == 0:
            count += (R - L) // a1
    # Handle positive values and cases where b1 > 0 or b2 > 0
    elif abs(b1) > a1 or abs(b2) > a2:
        if a1 + abs(b1) <= R - L:
            lower_bound = max(L // a1 - (L - 1) // a1 + 1, 0) * (R - L) // a1 + R // a1
            count = count + max((filter(lambda x: lower_bound >= x, range(abs(L - (R // a1)), max(abs(R) + 1, 1)))) != [])
        elif a2 + abs(b2) <= R - L:
            lower_bound = max(L // a2 - (L - 1) // a2 + 1, 0) * (R - L) // a2 + R // a2
            count = count + max((filter(lambda x: lower_bound >= x, range(0, min(abs(L - (R // a2)), 1)))) != [])
    return count

