from collections import defaultdict

def find(graph, start):
    visited = [False] * len(graph)
    stack = [start]
    path = set()

    while stack:
        vertex = stack.pop()
        if vertex not in visited:
            visited[vertex] = True
            path.add(vertex)
            stack.extend(graph[vertex] & set(stack) - {vertex})

    return path

def disjoint_forests(graph):
    components = defaultdict(set)
    for u, children in graph.items():
        component = set()
        for c in children:
            component.update(find(components, c))
        for u, children in graph.items():
            if u in component:
                components[u].update(component)

    return components

def cyclic_components(graph):
    def cycle(c):
        stack = [next(iter(c))]
        visited = set(stack)
        while stack:
            next_node = stack.pop()
            if next_node in c:
                return True
            for child in graph[next_node]:
                if cycle({next_node, *graph[next_node] - set(stack) - {next_node} | {child}}):
                    return True
                stack.update(graph[next_node])
            visited.update(stack)
            stack.clear()
        return False

    return {u for u in range(len(graph)) if cycle({u})}

def process_tunnels(n, m, tunnels):
    graph = defaultdict(set)
    for u, v in tunnels:
        graph[u].add(v)
        graph[v].add(u)

    components = disjoint_forests(graph)
    cyclic = cyclic_components(graph)

    return len(components), len(cyclic)

