def insert(lyrics, trie, x):
    count = 1
    for char in lyrics:
        if char in trie:
            trie = trie[char]
            count += 1
        else:
            break
    trie.total[x] = max(trie.total.get(x, 0), count)

def query(lyrics, query, trie):
    trie_total = trie.total.get(query, 0)
    trie_queries = trie.total.get(query, 0)
    result = (trie_total) - trie_queries if trie_queries > 0 else 0
    trie_queries = 0
    trie_total = 0
    for char in lyrics:
        trie = trie[char]
        result += trie.total.get(query, 0)
    return min(len(lyrics) - 1, result)

def solve(n, q, lyrics, queries):
