from collections import deque

def process_array(n, a, b):
    stack = deque()
    result = [0] * n
    stack.append(1)

    for i in range(n):
        while stack and (b[i] == '*' or (b[i] == '/' and (stack[-1] * a[i]) % a[i] == stack[-1])):
            result[i] = stack[-1]
            stack.pop()
        stack.append(a[i])

    return result

def count_simple_segments(n, a, b):
    result = 0
    stack = deque()

    for i in range(n):
        while stack and (b[i] == '*' or (b[i] == '/' and (stack[-1] * a[i]) % a[i] == stack[-1])):
            current_sum = 1
            for j in range(len(stack)):
                current_sum *= a[stack[j]]
                if current_sum % a[i] != 1:
                    break
            else:
                result += len(stack)
            stack.pop()

        if b[i] == '/':  # Handle left division which might exceed limits
            if stack[0] != 1:
                result -= 1
                while stack and a[stack[-1]] > 1:
                    if (stack[-1] - 1) * a[i] % a[i] == stack[-1]:
                        stack.pop()
                    else:
                        break
            else:
                result -= 1

        stack.append(i)

    return result

