def sum_after_operations(N: int, M: int, K: int, operations: List[List[int]]) -> int:
    MOD = 10**9 + 7
    row_sum = [0 for _ in range(M)]
    col_sum = [0 for _ in range(M)]

    # Pre-compute column wise sums
    for i in range(K):
        if operations[i][0] == 0:
            row_sum[operations[i][1] - 1] *= operations[i][2]
        else:
            col_sum[operations[i][1] - 1] *= operations[i][2]

    for x in range(1, M + 1):
        row_sum[x - 1] %= MOD
        if x:
            col_sum[x - 2] %= MOD

    # Calculate the total sum after operations
    total_sum = 0
    for j in range(M):
        for i in range(N):
            total_sum += (i + 1) * (j + 1) * (row_sum[j] + col_sum[j])
            total_sum %= MOD

    return total_sum

