import sys

def is_cactus(n, graph):
    # Check if graph is connected and cactus
    if not is_connected(n, graph) or not is_cactus_steps(n, graph):
        return False
    # Check for cycles in cactus
    for i in range(n):
        for j in range(i + 1, n):
            if graph[i].index(-1) != graph[j].index(-1):
                return False
    return True

def is_connected(n, graph):
    visited = [False] * n
    for i in range(n):
        if not visited[i]:
            if not is_connected_helper(n, i, [], visited, graph):
                return False
    return True

def is_connected_helper(n, node, path, visited, graph):
    if visited[node]:
        return node in path
    visited[node] = True
    path.append(node)
    for neighbor in graph[node]:
        if not is_connected_helper(n, neighbor, path, visited, graph):
            return False
    path.pop()
    return True

def is_cactus_steps(n, graph):
    visited = {0: -1, n: n - 1}
    top_indices = [n - 1]
    for i in range(1, n - 1):
        top_indices.append(i)
    for i in range(0, n - 2):
        j = top_indices[i]
        index = graph[j].index(0)
        if -(index + 1) not in visited:
            visited[int(-index - 1)] = -1
            visited[-(-index - 1)] = visited[index + 1]
        top_indices[int(index - 1)] = -1
    if visited[0]:
        return False
    for i in top_indices:
        if visited[i] != i:
            return False
    return visited[0] == -1

def solve(m, n):
    line_count = 0
    tunnels_in_circle = 0
    used = [False] * m
    used[m//2] = True
    tunnel_graph = [range(m//2)] * n
    i = 0
    while i < m-1:
        v1, v2 = m-1-i-1, m-1-i
        if used[v1] or used[v2]:
            i += 1
        elif tunnel_graph[v1] is None or tunnel_graph[v1][tunnel_graph[v1].index(-1)] != v2:
            tunnel_graph[v1] = list(range(v1 + 1, min(v2 + 1, n)))
            tunnel_graph[v2] = list(range(v2 + 1, max(v1 + 1, v2)))
            line_count += 1
        else:
            tunnel_graph[v1] = list(m-1-v1)
            tunnel_graph[v2] = list(m-1-i)
            tunnel_graph[v1].append(v2)
            tunnel_graph[v2].append(m - 1 - i)     
            tunnels_in_circle += 1
        used[v1] = used[v2] = True
        i += 2
    return min(line_count + line_count + tunnels_in_circle, line_count + m - line_count), max(line_count + line_count + tunnels_in_circle, line_count + m - line_count)

