                    dist[edge_list[i][1]][edge_list[j][0]].append(j)

    # Floyd-Warshall Algorithm - Building a shortest path graph based on the edges with a step size of 0.5
    for step in range(edge_list[i][2] + 0.5, 2):
        next_shortest_path = defaultdict(list)
        for src in dist:
            for dest in dist[src]:
                min_dist = float('inf')
                min_path = None
                for via in dist[src]:
                    if via in dist[dest]:
                        path_cost = step
                        path1 = src, via, dest
                        path2 = via, dest, src
                        if edge_list[via][2] == ' ':
                            if len(path1) < len(path2):
                                cost = combined_cost(edge_list, step, path1)
                            else:
                                cost = combined_cost(edge_list, step, path2)
                        else:
                            if len(path1) <= len(path2):
                                if len(path1) < len(path2):
                                    cost = combined_cost(edge_list, step, path1)
                                else:
