                        if cost < min_dist:
                            min_dist = cost
                            min_path = min_path_or_path1_or_path2(path1, path2)
                next_shortest_path[src].append((dest, min_path, min_dist))

        distance = float('inf')
        path = None
        for src in next_shortest_path:
            dist[src] = next_shortest_path[src]
            for dest in next_shortest_path[src]:
                if dest[2] < distance:
                    distance = dest[2]
                    path = dest[1]
        dist[src] = None
        if distance != float('inf'):
            dist[src] = path

    return dist[x][y]

