from collections import deque

def calculate_path(a, b, l, r):
    x = 1
    paths = []
    s = deque()

    for i in range(l, r + 1):
        if b[i] == '*':
            x *= a[i]
        elif b[i] == '/':
            if x % a[i] == 0:
                x //= a[i]
                s.append((x, i + 1))
            else:
                x /= a[i]
                s.append((x, i + 1))
        elif b[i] == '/':
            if x % a[i] == 0:
                paths.extend([(x, i + 1)] + list(s))
            else:
                paths.append(x)
        else:
            a[i] = 0
        s.clear()

    return paths

def count_simple_segments(n, a, b):
    total_paths = calculate_path(a, b, 1, n)

    # Filter out non-simple segments
    simple_paths = [p for p in total_paths if all(a[i] != 0 for i in p)]

    return len(simple_paths)

