        if (point, idx) in memo:
            return memo[(point, idx)]

        if point == 0:
            return 0
        if 0 < point < arr[idx] and 0 < arr[idx] - point < arr[idx+1] - arr[idx-1]:
            max_points += max(arr[idx]-point, point)
            max_points += dfs(0 if point < arr[idx] else point, idx+2)
