        results = dfs(point, idx+1)

        if point > arr[idx]:
            results += dfs(point-arr[idx], idx+1)

        if 0 < point < arr[idx]-1 and point < arr[idx]:
            results += dfs(point, idx+1)

        return max(results, max_points)

    dfs(point=abs(arr[0]-arr[1])+abs(arr[-1]-arr[-2]), idx=2)
    return max_points


