from collections import defaultdict, deque

def build_graph(edges):
    graph = defaultdict(list)
    for u, v, c in edges:
        graph[u].append((v, c))
        graph[v].append((u, c))
    return graph

def get_path_length(start, end, edges):
    queue = deque([(0, start, [start])])
    while queue:
        path_length, current_vertex, path = queue.popleft()
        if current_vertex == end:
            return path_length
        for neighbor, edge_label in graph[current_vertex]:
            if str(current_vertex, neighbor) not in lcp_map.keys():
                queue.append((path_length + 1, neighbor, path + [neighbor]))
    return -1

def get_minimum_length_path(source, query):
    if lcp_map[source][query] < 0:
        query_lcm_y, equals_y = query_next(source, query)
        if equals_y:
            y = query
            while y:
                if y < source:
                    lcp_map[source][query] += get_path_length(source, y - 1, edges)
                else:
                    lcp_map[source][query] += get_path_length(source, y - 1, b_lst[source])
                y //= 10
        else:
            y, b = query_next(source, query)
            while y:
                if y < source and lcp_map[source][query] < lcp_map[source][y]:
                    lcp_map[source][query] += get_path_length(source, y - 1, edges)
                else:
                    lcp_map[source][query] += get_path_length(source, y - 1, b_lst[source])
                y //= 10
    return lcp_map[source][query]

def query_and_return_result(source, target):
    y = get_minimum_length_path(source, target)
    if y >= 0:
        l, r = y, y + 1000
        while l <= r:
            mid_y = (l + r) // 2
            result = get_minimum_length_path(source, mid_y)
            if result <= mid_y:
                l = mid_y + 1
            else:
                r = mid_y - 1
        return get_minimum_length_path(source, l) == target
    else:
