# Function to get the smallest prime factor for a number
def smallest_prime_factor(x):
    while x % 2 == 0:
        x //= 2
    while x % 3 == 0:
        x //= 3
    while x % 5 == 0:
        x //= 5
    for i in range(7, int(pow(x, 0.5)) + 1, 2):
        if x % i == 0:
            return i
    return x

# Function to get the Euler's Totient function value for a number
def euler_totient(n):
    pi = smallest_prime_factor(n)
    if n % pi == 0:
        return n / pi
    else:
        return n * (1 - 1/pow(pi, 1))

# Function to get the prime factorization of a number
def prime_factors(n):
    result = defaultdict(int)
    for i in range(2, int(pow(n, 0.5)) + 1):
        while n % i == 0:
            result[i] += 1
            n //= i
    if n > 1:
        result[n] += 1
    return result

# Calculate the number of simple segments [l; r]
def simple_segments(n, a, b):
    e = list(map(euler_totient, a))
    g = defaultdict(int)
    g[1] = 1
    for i in range(n - 1):
        g[e[i] * e[i + 1]] += 1
    subsets = []
    for subset in g:
        subsets.append(prime_factors(subset))
        # Generate all possible subsets of the current subset
        for s_subset in subsets:
            for s in range(len(s_subset)):
                if len(subset) > 0 and subset[s] != 0:
                    if s_subset[s] == 0:
                        s_subset[s] = 1
                    else:
                        s_subset[s] += 1
                elif any(s_subset[s] for s in range(len(s_subset))):
                    break
            g[prime_factors(subset) + prime_factors(s_subset)] += 1
            subsets.remove(s_subset)
    return sum(g[key] for key in g if max(g[key]) == n)

