            dp[i] %= 1_000_000_007
        counts[i] += dp[i]
    return sum(counts.values()) % 1_000_000_007

def solve(input_data):
    n = int(input_data[0])
    arr = list(map(int, input_data[1].split()))
    return count_right_permutations(n, arr)

# Sample input
input_data = ["3", "1 2 4"]
print(solve(input_data))
